mapper.select:
SELECT p.*, COALESCE(rs.review_count, 0) AS reviewCount, COALESCE(rs.average_rating, 0) AS averageRating
FROM product p
LEFT JOIN (
  SELECT product_id, COUNT(*) AS review_count, ROUND(AVG(rating), 1) AS average_rating
  FROM review WHERE deleted = 0 AND status = 1 AND parent_id = 0 GROUP BY product_id
) rs ON rs.product_id = p.id
WHERE p.deleted = 0 AND p.status = 1
AND (p.name LIKE CONCAT('%', #{keyword}, '%') OR p.subtitle LIKE CONCAT('%', #{keyword}, '%'))
AND p.category_id = #{categoryId}
AND p.brand_id = #{brandId}
AND p.price >= #{minPrice}
AND p.price <= #{maxPrice}
AND COALESCE(rs.average_rating, 0) >= #{minRating}
AND p.total_stock > 0

  ORDER BY p.sales DESC, p.id DESC
  ORDER BY p.price ASC, p.id DESC
  ORDER BY p.price DESC, p.id DESC
  ORDER BY COALESCE(rs.average_rating, 0) DESC, COALESCE(rs.review_count, 0) DESC, p.id DESC
  ORDER BY p.create_time DESC, p.id DESC
  ORDER BY p.is_recommend DESC, p.id DESC

SELECT p.*, COALESCE(rs.review_count, 0) AS reviewCount, COALESCE(rs.average_rating, 0) AS averageRating
FROM product p
LEFT JOIN (SELECT product_id, COUNT(*) review_count, ROUND(AVG(rating),1) average_rating FROM review WHERE deleted=0 AND status=1 AND parent_id=0 GROUP BY product_id) rs ON rs.product_id=p.id
WHERE p.deleted=0 AND p.status=1 AND p.id != #{productId}
  AND (p.category_id=#{categoryId} OR p.brand_id=#{brandId})
ORDER BY (p.category_id=#{categoryId}) DESC, p.sales DESC, p.id DESC LIMIT #{limit}
